var PART_INDEX_BY_FUNCTION = (() => {
  const idx = {};
  for (const p of ROCKET_PARTS2) {
    if (!idx[p.type]) idx[p.type] = [];
    idx[p.type].push(p.id);
  }
  return idx;
})();
var PART_INDEX_BY_SIZE = (() => {
  const idx = { "size_0": [], "size_1": [], "size_2": [], "size_3": [], "size_4": [], "unknown": [] };
  for (const p of ROCKET_PARTS2) {
    const d = p.diameter || 0;
    if (d === 0 || d <= 0.625) idx["size_0"].push(p.id);
    else if (d <= 1.25) idx["size_1"].push(p.id);
    else if (d <= 2.5) idx["size_2"].push(p.id);
    else if (d <= 3.75) idx["size_3"].push(p.id);
    else idx["size_4"].push(p.id);
  }
  return idx;
})();
var PART_INDEX_BY_TECH_LEVEL = (() => {
  const idx = { tier_1: [], tier_2: [], tier_3: [], tier_4: [], tier_5: [], tier_0: [] };
  const tierMap = {
    "basic_rocketry": "tier_1",
    "stability": "tier_1",
    "survivability": "tier_1",
    "advanced_rocketry": "tier_2",
    "flight_control": "tier_2",
    "landing_techniques": "tier_2",
    "advanced_aerodynamics": "tier_2",
    "space_exploration": "tier_3",
    "propulsion_systems": "tier_3",
    "heavy_lift": "tier_3",
    "precision_navigation": "tier_3",
    "isru_mining": "tier_3",
    "orbital_construction": "tier_3",
    "advanced_life_support": "tier_3",
    "nuclear_engineering": "tier_3",
    "deep_space_comm": "tier_3",
    "advanced_landing": "tier_3",
    "advanced_propulsion": "tier_4",
    "fusion_power": "tier_4",
    "plasma_propulsion": "tier_4",
    "asteroid_mining": "tier_4",
    "interstellar_travel": "tier_5",
    "warp_theory": "tier_5",
    "antimatter_tech": "tier_5",
    "colony_engineering": "tier_5"
  };
  for (const p of ROCKET_PARTS2) {
    const tech = p.techRequired || "";
    const tier = tierMap[tech] || "tier_0";
    idx[tier].push(p.id);
  }
  return idx;
})();
var PART_INDEX_BY_MASS = (() => {
  const idx = { "ultralight": [], "light": [], "medium": [], "heavy": [], "super_heavy": [], "mega": [] };
  for (const p of ROCKET_PARTS2) {
    const m = p.mass + (p.fuelMass || 0);
    if (m <= 50) idx["ultralight"].push(p.id);
    else if (m <= 200) idx["light"].push(p.id);
    else if (m <= 1e3) idx["medium"].push(p.id);
    else if (m <= 5e3) idx["heavy"].push(p.id);
    else if (m <= 2e4) idx["super_heavy"].push(p.id);
    else idx["mega"].push(p.id);
  }
  return idx;
})();
var PART_INDEX_BY_COST = (() => {
  const idx = { "budget": [], "low": [], "mid": [], "high": [], "premium": [], "flagship": [] };
  for (const p of ROCKET_PARTS2) {
    const c = p.cost;
    if (c <= 100) idx["budget"].push(p.id);
    else if (c <= 1e3) idx["low"].push(p.id);
    else if (c <= 1e4) idx["mid"].push(p.id);
    else if (c <= 5e4) idx["high"].push(p.id);
    else if (c <= 2e5) idx["premium"].push(p.id);
    else idx["flagship"].push(p.id);
  }
  return idx;
})();

