  botCap.position.y = -h / 2;
  botCap.rotation.x = Math.PI;
  botCap.castShadow = true;
  group.add(botCap);
  const flangeMat = new MeshStandardMaterial2({
    map: texBrushedMetal("steel", 512),
    color: 10066329,
    metalness: 0.85,
    roughness: 0.2
  });
  const boltMat = new MeshStandardMaterial2({ color: 3355443, metalness: 0.8, roughness: 0.3 });
  const boltCount = sizeClass === 3 ? 32 : sizeClass === 2 ? 24 : 16;
  const topFlange = new Mesh2(new TorusGeometry2(r * 1.04, 0.05, 12, 56), flangeMat);
  topFlange.position.y = h / 2 + 0.58;
