  for (let i = 0; i < 4; i++) {
    const a = i / 4 * Math.PI * 2 + Math.PI / 8;
    group.add(makeLabelDecal(r * 1.012, h * 0.28, a, 0.16, 0.05, hazardMat));
    group.add(makeLabelDecal(r * 1.012, -h * 0.28, a + Math.PI / 4, 0.12, 0.1, textMat));
  }
