    const cap = new Mesh2(new SphereGeometry2(0.042, 12, 8), new MeshStandardMaterial2({ color: 13378082, metalness: 0.4, roughness: 0.5 }));
    cap.position.set(sign2 * r * 1.08, h * 0.42, 0);
