  oring.rotation.x = Math.PI / 2;
  group.add(oring);
  const grooveMat = new MeshStandardMaterial2({ color: 3355443, metalness: 0.5, roughness: 0.7 });
  const groove = new Mesh2(new TorusGeometry2(nozzleR * 0.36, 0.012, 8, 48), grooveMat);
  groove.position.y = nozzleH / 2 + 0.395;
  groove.rotation.x = Math.PI / 2;
  group.add(groove);
  const oring2 = new Mesh2(new TorusGeometry2(nozzleR * 0.33, 6e-3, 8, 48), oringMat);
  oring2.position.y = nozzleH / 2 + 0.398;
  oring2.rotation.x = Math.PI / 2;
  group.add(oring2);
  const ceramicMat = new MeshStandardMaterial2({ color: 15658734, metalness: 0, roughness: 0.3 });
