  ceramicInsulator.position.y = nozzleH / 2 + 0.35;
  group.add(ceramicInsulator);
  const electrodeMat = new MeshStandardMaterial2({ color: 14540253, metalness: 0.9, roughness: 0.1 });
  const electrode = new Mesh2(new CylinderGeometry2(3e-3, 3e-3, 0.02, 8), electrodeMat);
  electrode.position.y = nozzleH / 2 + 0.375;
  group.add(electrode);
  const sparkGlowMat = new MeshStandardMaterial2({ color: 16777096, emissive: 16777028, emissiveIntensity: 2, transparent: true, opacity: 0.6 });
  const sparkGlow = new Mesh2(new SphereGeometry2(6e-3, 8, 6), sparkGlowMat);
  sparkGlow.position.y = nozzleH / 2 + 0.33;
  group.add(sparkGlow);
  const mufflerMat = new MeshStandardMaterial2({ map: texBrushedMetal("steel", 256), color: 5592405, metalness: 0.7, roughness: 0.4 });
  const muffler = new Mesh2(new CylinderGeometry2(0.05, 0.05, 0.15, 16), mufflerMat);
