  const bodyNormal = texNormalDetail("panels", 1024);
  bodyNormal.repeat.set(2, 1);
  const bodyRough = texRoughnessMap(0.35, 1024);
  bodyRough.repeat.set(2, 1);
  const bodyGeo = new CylinderGeometry2(r, r, h, 56);
