  nosePts.push(new Vector22(r * 0.04, h / 2 + r * 1.85));
  nosePts.push(new Vector22(r * 0.1, h / 2 + r * 1.75));
  nosePts.push(new Vector22(r * 0.18, h / 2 + r * 1.62));
  nosePts.push(new Vector22(r * 0.28, h / 2 + r * 1.48));
  nosePts.push(new Vector22(r * 0.38, h / 2 + r * 1.32));
  nosePts.push(new Vector22(r * 0.48, h / 2 + r * 1.15));
  nosePts.push(new Vector22(r * 0.58, h / 2 + r * 0.96));
