  group.add(insul);
  const coverMat = new MeshStandardMaterial2({ map: texBrushedMetal("aluminum", 256), color: 13421772, metalness: 0.7, roughness: 0.25 });
  const cover = new Mesh2(new SphereGeometry2(0.05, 12, 8, 0, Math.PI * 2, 0, Math.PI / 2), coverMat);
  cover.position.y = 0.075;
  cover.scale.y = 0.5;
  cover.castShadow = true;
