  const exitRingMat = new MeshStandardMaterial2({ map: makeMetalTexture("steel"), metalness: 0.88, roughness: 0.25 });
  const exitRing = new Mesh2(new TorusGeometry2(r * 1.01, 0.025, 8, 48), exitRingMat);
