      attitudeError: imu.attitudeError.length(),
      positionError: imu.positionError.length(),
      velocityError: imu.velocityError.length(),
      driftTime: imu.timeSinceCorrection,
      gyroBias: imu.gyroBias.length(),
      accelBias: imu.accelBias.length()
