    trn.matchedPoints = matchedPoints;
    trn.positionFix.x = bestX + (Math.random() - 0.5) * trn.matchResolution;
    trn.positionFix.y = bestY + (Math.random() - 0.5) * trn.matchResolution;
    trn.positionFix.z = altitude;
