    this._animateNumber("hud-alt", data.altitude >= 1e3 ? `${(data.altitude / 1e3).toFixed(2)} km` : `${data.altitude.toFixed(0)} m`);
    this._animateNumber("hud-speed", `${data.speed.toFixed(1)} m/s`);
    this._animateNumber("hud-dv", `${data.deltaV.toFixed(0)} m/s`);
    this._animateNumber("hud-twr", data.twr.toFixed(2));
