var HALO_CLUSTER_RADIAL_PROFILE = [];
(function generateHaloClusters() {
  for (let i = 0; i < 30; i++) {
    const u = Math.random();
    const rMin = 1e4;
    const rMax = GALACTIC_HALO_RADIUS_LY * 0.8;
    let r = rMin * Math.pow(1 - u * (1 - Math.pow(rMin / rMax, 2.5)), -1 / 2.5);
    r = Math.min(r, rMax);
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.acos(2 * Math.random() - 1);
    const z = r * Math.cos(phi);
    r = r * Math.sin(phi);
    HALO_CLUSTER_RADIAL_PROFILE.push({ r, theta, z });
  }
})();
