  /** 迭代2: 生涯模式发射扣费检查 */
  tryDeductLaunchCost() {
    if (this.gameMode !== "career" && this.gameMode !== "extreme") return true;
    let cost = this.calculateLaunchCost();
    if (this.gameMode === "extreme") cost = Math.round(cost * 1.3);
    if (this.gameMode === "custom") cost = Math.round(cost * this.customSettings.fundsMultiplier);
    if (this.funds < cost) {
      this.hud.showNotification(`\u274C \u8D44\u91D1\u4E0D\u8DB3! \u9700\u8981${cost}\uFF0C\u5F53\u524D${Math.floor(this.funds)}`, 3e3);
      return false;
    }
    this.funds -= cost;
    this.lastLaunchCost = cost;
    this.hud.showNotification(`\u{1F680} \u53D1\u5C04\u6D88\u8017\u8D44\u91D1: ${cost} (\u5269\u4F59${Math.floor(this.funds)})`, 3e3);
    this.recordFundsSpent(cost);
    this.addTimelineEvent("launch_cost", `\u53D1\u5C04\u6210\u672C: ${cost}\u{1F4B0}`, "\u{1F4B0}");
    return true;
  }
