// src/index.ts
var container2 = document.getElementById("app");
if (!container2) {
  throw new Error("\u672A\u627E\u5230\u5E94\u7528\u5BB9\u5668");
}
var currentGame = null;
var currentQuality = "high";
function startGame(parts) {
  if (currentGame) {
    currentGame.dispose();
    currentGame = null;
  }
  currentGame = new Game2(container2, currentQuality, parts);
  currentGame.showHUD();
  currentGame.onExit = () => {
    if (currentGame) {
      currentGame.dispose();
      currentGame = null;
    }
    enterSpaceCenter();
  };
}
function enterSpaceCenter() {
  const sc = new (void 0)({
    onLaunch: () => {
      const parts = sc.getSelectedParts();
      sc.destroy();
      if (parts.length === 0) {
        startGame();
      } else {
        startGame(parts);
      }
    },
    onBack: () => {
      sc.destroy();
      location.reload();
    }
  });
}
var menu = new (void 0)((quality) => {
  currentQuality = quality;
  enterSpaceCenter();
});
